let diagnosticCodes = ["SYNTAX", "ORPHAN", "DUPLICATE", "KEY_NO_DECOMP", "KEY_UNREACHABLE", "SYNON_UNUSED", "PRE_CHAIN", "SYNON_UNKNOWN", "RULE_NO_REASM", "RULE_SHADOWED", "REF_UNBOUND", "TARGET_UNDEFINED", "TARGET_CYCLE"]
let errorCodes: Set<String> = ["SYNTAX", "ORPHAN", "DUPLICATE", "SYNON_UNKNOWN", "REF_UNBOUND", "TARGET_UNDEFINED", "TARGET_CYCLE"]

func references(_ text: String) -> [Int] {
    let bytes = Array(text.utf8)
    guard bytes.count >= 3 else { return [] }
    return (0..<(bytes.count - 2)).compactMap { index in
        bytes[index] == 40 && (48...57).contains(bytes[index + 1]) && bytes[index + 2] == 41 ? Int(bytes[index + 1] - 48) : nil
    }
}

func lint(_ script: Script) -> [Diagnostic] {
    var found = script.diagnostics
    func add(_ line: Int, _ code: String, _ message: String) { found.append(Diagnostic(line: line, code: code, message: message)) }
    let replacementWords = Set(script.pres.flatMap { $0.replacement })
    let targets = Set(script.items.filter { ["GOTO", "RESTATE"].contains($0.kind) }.map { $0.arguments[0] })
    let usedGroups = Set(script.rules.flatMap { $0.pattern }.filter { $0.hasPrefix("@") }.map { String($0.dropFirst()) })
    var graph: [String: [String]] = [:]
    for keyword in script.keywords {
        graph[keyword.word] = keyword.decomps.flatMap { script.rules[$0].items }.map { script.items[$0] }.filter {
            ["GOTO", "RESTATE"].contains($0.kind) && script.keywordMap[$0.arguments[0]] != nil
        }.map { $0.arguments[0] }
    }
    func reaches(_ start: String, _ goal: String) -> Bool {
        var seen: Set<String> = []
        var pending = [start]
        while let word = pending.popLast() {
            if word == goal { return true }
            if seen.insert(word).inserted { pending += graph[word]! }
        }
        return false
    }
    func unknown(_ pattern: [String]) -> [String] {
        pattern.filter { $0.hasPrefix("@") && script.groupWords[String($0.dropFirst())] == nil }
    }
    for keyword in script.keywords {
        if keyword.decomps.isEmpty { add(keyword.line, "KEY_NO_DECOMP", "keyword \(keyword.word) has no DECOMP") }
        if script.pre[keyword.word] != nil && !replacementWords.contains(keyword.word) && !targets.contains(keyword.word) { add(keyword.line, "KEY_UNREACHABLE", "keyword \(keyword.word) is replaced by PRE") }
        for rules in [keyword.memories, keyword.decomps] {
            for (position, ruleID) in rules.enumerated() {
                let rule = script.rules[ruleID]
                for element in unknown(rule.pattern) { add(rule.line, "SYNON_UNKNOWN", "unknown group \(element.dropFirst())") }
                if rule.items.isEmpty { add(rule.line, "RULE_NO_REASM", "rule has no reassembly") }
                if unknown(rule.pattern).isEmpty, let shadow = rules.prefix(position).map({ script.rules[$0] }).first(where: {
                    unknown($0.pattern).isEmpty && patternCovers($0.pattern, later: rule.pattern, groups: script.groupWords)
                }) { add(rule.line, "RULE_SHADOWED", "pattern is shadowed by line \(shadow.line)") }
                let wildcards = rule.pattern.filter(isWildcard).count
                for itemID in rule.items {
                    let item = script.items[itemID]
                    let refs: [Int]
                    if item.kind == "REASM" { refs = references(item.text) }
                    else if item.kind == "RESTATE" { refs = item.arguments.dropFirst().filter(isReference).map { Int(Array($0.utf8)[1] - 48) } }
                    else { refs = [] }
                    for reference in refs where reference == 0 || reference > wildcards { add(item.line, "REF_UNBOUND", "reference (\(reference)) is not bound") }
                    if ["GOTO", "RESTATE"].contains(item.kind) {
                        let target = item.arguments[0]
                        if script.keywordMap[target] == nil { add(item.line, "TARGET_UNDEFINED", "target \(target) is not a keyword") }
                        else if reaches(target, keyword.word) { add(item.line, "TARGET_CYCLE", "edge \(keyword.word) -> \(target) is on a cycle") }
                    }
                }
            }
        }
    }
    for group in script.groups where !usedGroups.contains(group.name) { add(group.line, "SYNON_UNUSED", "group \(group.name) is never used") }
    for pre in script.pres {
        for word in pre.replacement where script.pre[word] != nil { add(pre.line, "PRE_CHAIN", "replacement \(word) is itself replaced by PRE") }
    }
    return found.enumerated().sorted {
        if $0.element.line != $1.element.line { return $0.element.line < $1.element.line }
        let left = diagnosticCodes.firstIndex(of: $0.element.code)!
        let right = diagnosticCodes.firstIndex(of: $1.element.code)!
        return left == right ? $0.offset < $1.offset : left < right
    }.map { $0.element }
}

func lintLines(_ diagnostics: [Diagnostic]) -> [String] {
    if diagnostics.isEmpty { return ["OK"] }
    let errors = diagnostics.filter { errorCodes.contains($0.code) }.count
    return diagnostics.map { "\($0.line) \($0.code) \($0.message)" } + ["TOTAL \(diagnostics.count) errors=\(errors) warnings=\(diagnostics.count - errors)"]
}

import Foundation

let sources = ["keyword", "memory", "question", "default", "repeat"]
let cycledLists = ["DEFAULT", "QUESTION", "REPEAT"]

func normalize(_ text: String) -> [[String]] {
    text.lowercased().components(separatedBy: CharacterSet(charactersIn: ",.?!;")).map { part in
        String(decoding: part.utf8.map { byte in
            (97...122).contains(byte) || (48...57).contains(byte) || byte == 39 ? byte : 32
        }, as: UTF8.self).split(separator: " ").map {
            String($0).trimmingCharacters(in: CharacterSet(charactersIn: "'"))
        }.filter { !$0.isEmpty }
    }.filter { !$0.isEmpty }
}

func groupedLines(_ values: [String], width: Int) -> [String] {
    stride(from: 0, to: values.count, by: width).map { start in
        values[start..<min(start + width, values.count)].joined(separator: " ")
    }
}

func rankedCounts(_ counts: [String: Int]) -> String {
    let values = counts.filter { $0.value > 0 }.sorted { $0.value == $1.value ? $0.key < $1.key : $0.value > $1.value }
    return values.isEmpty ? "none" : values.prefix(5).map { "\($0.key) \($0.value)" }.joined(separator: ", ")
}

func sourceLine(_ turns: Int, counts: [String: Int]) -> String {
    "turns=\(turns) " + sources.map { "\($0)=\(counts[$0]!)" }.joined(separator: " ")
}

final class Snapshot {
    let state: BotState
    init(_ state: BotState) { self.state = state }
}

struct Session {
    let name: String
    var turns = 0
    var counts = Dictionary(uniqueKeysWithValues: sources.map { ($0, 0) })
    var previous: [[String]]?
    var history: [String] = []
    var lastTrace: [String]?
    var traceOn = false
    var topics: [String: Int] = [:]
    var words: [String: Int] = [:]
    var stored = 0
    var recalled = 0
    var unrecognized: [Int] = []
    var undo: Snapshot?
}

struct BotState {
    var positions: [Int]
    var hits: [Int]
    var itemUses: [Int]
    var keywordUses: [Int]
    var keywordReplies: [Int]
    var listPositions = Dictionary(uniqueKeysWithValues: cycledLists.map { ($0, 0) })
    var memory: MemoryQueue
    var session = Session(name: "")

    init(script: Script) {
        positions = Array(repeating: 0, count: script.rules.count)
        hits = Array(repeating: 0, count: script.rules.count)
        itemUses = Array(repeating: 0, count: script.items.count)
        keywordUses = Array(repeating: 0, count: script.keywords.count)
        keywordReplies = Array(repeating: 0, count: script.keywords.count)
        memory = MemoryQueue(capacity: script.capacity)
    }
}

final class Chatbot {
    let script: Script
    var state: BotState
    var transcript: [String] = []
    var totalTurns = 0
    var totalSources = Dictionary(uniqueKeysWithValues: sources.map { ($0, 0) })

    init(script: Script) { self.script = script; state = BotState(script: script) }
    func logPrefix() -> String { "\(state.session.name) \(state.session.turns)" }
    func resetCycles() {
        state.positions = Array(repeating: 0, count: script.rules.count)
        for name in cycledLists { state.listPositions[name] = 0 }
    }
    func takeText(_ name: String) -> String {
        let texts = script.texts[name]!
        let position = state.listPositions[name]!
        state.listPositions[name] = (position + 1) % texts.count
        return texts[position]
    }
    func takeItem(_ ruleID: Int) -> (number: Int, item: Item) {
        let rule = script.rules[ruleID]
        let position = state.positions[ruleID]
        let itemID = rule.items[position]
        state.itemUses[itemID] += 1
        state.positions[ruleID] = (position + 1) % rule.items.count
        return (position + 1, script.items[itemID])
    }
    func preSubstitute(_ clauses: [[String]]) -> [[String]] {
        clauses.map { $0.flatMap { script.pre[$0] ?? [$0] } }
    }
    func prepared(_ text: String) -> [[String]] { preSubstitute(normalize(text)) }
    func isQuit(_ text: String) -> Bool {
        let words = normalize(text).flatMap { $0 }
        return words.count == 1 && script.quit.contains(words[0])
    }
    func selectClause(_ clauses: [[String]]) -> (number: Int, words: [String])? {
        for (index, clause) in clauses.enumerated() where clause.contains(where: { script.keywordMap[$0] != nil }) {
            return (index + 1, clause)
        }
        return nil
    }
    func keywordList(_ words: [String]) -> [Int] {
        var found: [Int] = []
        var seen: Set<Int> = []
        for word in words {
            if let id = script.keywordMap[word], seen.insert(id).inserted { found.append(id) }
        }
        return found.enumerated().sorted {
            let left = script.keywords[$0.element].rank
            let right = script.keywords[$1.element].rank
            return left == right ? $0.offset < $1.offset : left > right
        }.map { $0.element }
    }
    func ruleEntries(_ keyword: Keyword) -> [(label: String, number: Int, id: Int)] {
        keyword.memories.enumerated().map { ("memory", $0.offset + 1, $0.element) }
            + keyword.decomps.enumerated().map { ("decomp", $0.offset + 1, $0.element) }
    }
    func findRule(_ rules: [Int], words: [String]) -> (number: Int, id: Int, bindings: [[String]])? {
        for (index, ruleID) in rules.enumerated() {
            if let bindings = matchPattern(script.rules[ruleID].pattern, words: words, groups: script.groupWords) {
                return (index + 1, ruleID, bindings)
            }
        }
        return nil
    }
    func keywordReply(_ clauses: [[String]], trace: inout [String]) -> String? {
        guard let selected = selectClause(clauses) else { trace.append("CLAUSE none"); return nil }
        let words = selected.words
        trace.append("CLAUSE \(selected.number) \(words.joined(separator: " "))")
        let keys = keywordList(words)
        trace.append("KEYS " + keys.map { script.keywords[$0].word }.joined(separator: " "))
        let first = script.keywords[keys[0]]
        if let memory = findRule(first.memories, words: words) {
            trace.append("MEMORY \(first.word) \(memory.number)")
            state.hits[memory.id] += 1
            if !script.rules[memory.id].items.isEmpty {
                let text = buildReply(takeItem(memory.id).item.text, bindings: memory.bindings, post: script.post)
                let prefix = logPrefix()
                if state.memory.store(prefix, keyword: first.word, text: text) { state.session.stored += 1 }
            }
        }
        var entered: Set<Int> = []
        for original in keys {
            if entered.contains(original) { continue }
            var current = original
            var currentWords = words
            trace.append("ENTER \(script.keywords[current].word)")
            while true {
                entered.insert(current)
                state.keywordUses[current] += 1
                let keyword = script.keywords[current]
                guard let found = findRule(keyword.decomps, words: currentWords) else { trace.append("NOMATCH \(keyword.word)"); break }
                state.hits[found.id] += 1
                if script.rules[found.id].items.isEmpty { trace.append("DECOMP \(keyword.word) \(found.number) 0"); break }
                let taken = takeItem(found.id)
                let item = taken.item
                trace.append("DECOMP \(keyword.word) \(found.number) \(taken.number)")
                if item.kind == "REASM" {
                    state.keywordReplies[current] += 1
                    state.session.topics[keyword.word, default: 0] += 1
                    return buildReply(item.text, bindings: found.bindings, post: script.post)
                }
                if item.kind == "NEWKEY" { break }
                let targetWord = item.arguments[0]
                guard let target = script.keywordMap[targetWord], !entered.contains(target) else { trace.append("BLOCKED \(targetWord)"); break }
                if item.kind == "RESTATE" {
                    currentWords = restatedWords(Array(item.arguments.dropFirst()), bindings: found.bindings)
                    trace.append((["RESTATE", targetWord] + currentWords).joined(separator: " "))
                } else { trace.append("GOTO \(targetWord)") }
                current = target
            }
        }
        return nil
    }

    func decide(_ text: String) -> (reply: String, trace: [String]) {
        let clauses = normalize(text)
        var trace: [String] = []
        let reply: String
        let source: String
        if !script.texts["REPEAT"]!.isEmpty && !clauses.isEmpty && clauses == state.session.previous {
            trace.append("REPEAT"); reply = takeText("REPEAT"); source = "repeat"
        } else if let keyword = keywordReply(preSubstitute(clauses), trace: &trace) {
            reply = keyword; source = "keyword"
        } else if !state.memory.texts.isEmpty {
            state.session.recalled += 1
            let prefix = logPrefix()
            reply = state.memory.recall(prefix); source = "memory"
        } else if text.hasSuffix("?") && !script.texts["QUESTION"]!.isEmpty {
            reply = takeText("QUESTION"); source = "question"
        } else { reply = takeText("DEFAULT"); source = "default" }
        trace.append("REPLY \(source)")
        state.session.previous = clauses
        state.session.counts[source]! += 1
        if ["question", "default"].contains(source) { state.session.unrecognized.append(state.session.turns) }
        return (reply, trace)
    }

    func respond(_ text: String) {
        var snapshot = state
        snapshot.session.undo = nil
        state.session.undo = Snapshot(snapshot)
        state.session.turns += 1
        for word in normalize(text).flatMap({ $0 }) where !script.stop.contains(word) { state.session.words[word, default: 0] += 1 }
        state.session.history.append("\(state.session.turns): \(text)")
        let result = decide(text)
        transcript += elizaLines(result.reply)
        state.session.lastTrace = result.trace
        if state.session.traceOn { transcript += result.trace.map { "  \($0)" } }
    }

    func command(_ line: String) -> [String] {
        let split = line.firstIndex(of: " ")
        let name = split.map { String(line[..<$0]) } ?? line
        let text = split.map { String(line[line.index(after: $0)...]) } ?? ""
        let args = text.isEmpty ? [] : text.components(separatedBy: " ")
        let none: Set<String> = [":keys", ":why", ":history", ":memory", ":forget", ":reset", ":unused", ":stats", ":undo"]
        let some: Set<String> = [":prepare", ":reflect", ":say", ":explain"]
        let one: Set<String> = [":groups", ":find", ":script", ":cycles", ":coverage"]
        guard none.union(some).union(one).union([":trace", ":test"]).contains(name) else { return ["unknown command \(name)"] }
        if none.contains(name) && !args.isEmpty || some.contains(name) && text.isEmpty || one.contains(name) && args.count != 1 || name == ":trace" && args != ["on"] && args != ["off"] || name == ":test" && args.count < 2 { return ["bad arguments"] }
        if [":script", ":cycles", ":coverage", ":test"].contains(name) && script.keywordMap[args[0]] == nil { return ["unknown keyword \(args[0])"] }
        switch name {
        case ":prepare":
            let clauses = prepared(text)
            var result = clauses.enumerated().map { "clause \($0.offset + 1): \($0.element.joined(separator: " "))" }
            if clauses.isEmpty { result.append("no words") }
            if let selected = selectClause(clauses) {
                result.append("selected \(selected.number)")
                result.append("keys " + keywordList(selected.words).map { "\(script.keywords[$0].word)/\(script.keywords[$0].rank)" }.joined(separator: " "))
            } else { result.append("selected none") }
            return result
        case ":test":
            let utterance = text.firstIndex(of: " ").map { String(text[text.index(after: $0)...]) } ?? ""
            let words = prepared(utterance).flatMap { $0 }
            let result = ruleEntries(script.keywords[script.keywordMap[args[0]]!]).map { entry -> String in
                let detail: String
                if let bindings = matchPattern(script.rules[entry.id].pattern, words: words, groups: script.groupWords) {
                    detail = bindings.isEmpty ? "match" : bindings.map { "[\($0.joined(separator: " "))]" }.joined(separator: " ")
                } else { detail = "no match" }
                return "\(entry.label) \(entry.number): \(detail)"
            }
            return result.isEmpty ? ["no rules"] : result
        case ":reflect":
            let clauses = prepared(text)
            return clauses.isEmpty ? ["no words"] : clauses.map { reflect($0, post: script.post).joined(separator: " ") }
        case ":keys":
            let keys = script.keywords.sorted { $0.rank == $1.rank ? $0.word < $1.word : $0.rank > $1.rank }
            return groupedLines(keys.map { "\($0.word)/\($0.rank)" }, width: 8)
        case ":groups":
            let names = script.groups.filter { $0.members.contains(args[0]) }.map { $0.name }.sorted()
            return [names.isEmpty ? "none" : names.joined(separator: " ")]
        case ":find": return find(args[0])
        case ":script":
            let keyword = script.keywords[script.keywordMap[args[0]]!]
            let numbers = [keyword.line] + (keyword.memories + keyword.decomps).flatMap { id in
                [script.rules[id].line] + script.rules[id].items.map { script.items[$0].line }
            }
            return numbers.sorted().map { "\($0) \(script.lines[$0 - 1])" }
        case ":why": return state.session.lastTrace ?? ["no reply yet"]
        case ":trace": state.session.traceOn = args[0] == "on"; return ["trace \(args[0])"]
        case ":history": return state.session.history.isEmpty ? ["no turns yet"] : Array(state.session.history.suffix(5))
        case ":memory": return ["memory \(state.memory.texts.count)/\(state.memory.capacity)"] + state.memory.texts.enumerated().map { "\($0.offset + 1): \($0.element)" }
        case ":forget":
            let count = state.memory.texts.count
            let prefix = logPrefix()
            state.memory.clear(prefix)
            return ["forgot \(count)"]
        case ":cycles", ":coverage":
            let entries = ruleEntries(script.keywords[script.keywordMap[args[0]]!])
            let result = entries.map { entry -> String in
                let rule = script.rules[entry.id]
                let details: String
                if name == ":cycles" { details = rule.items.isEmpty ? "empty" : "next \(state.positions[entry.id] + 1)/\(rule.items.count)" }
                else {
                    let uses = rule.items.map { String(state.itemUses[$0]) }.joined(separator: " ")
                    details = "hits \(state.hits[entry.id]) entries \(uses.isEmpty ? "-" : uses)"
                }
                return "\(entry.label) \(entry.number): \(details)"
            }
            return result.isEmpty ? ["no rules"] : result
        case ":reset": resetCycles(); return ["cycles reset"]
        case ":unused":
            let numbers = script.items.indices.filter { state.itemUses[$0] == 0 }.map { script.items[$0].line }.sorted()
            return ["unused \(numbers.count)"] + groupedLines(numbers.map(String.init), width: 12)
        case ":stats": return [sourceLine(state.session.turns, counts: state.session.counts)]
        case ":say", ":explain":
            if isQuit(text) { return ["would quit"] }
            let saved = state
            let result = decide(text)
            state = saved
            return name == ":say" ? [result.reply] : result.trace
        default:
            guard let snapshot = state.session.undo else { return ["nothing to undo"] }
            state = snapshot.state
            return ["undone turn \(state.session.turns + 1)"]
        }
    }

    func find(_ word: String) -> [String] {
        var result: [String] = []
        if let id = script.keywordMap[word] { result.append("keyword rank \(script.keywords[id].rank)") }
        for (label, substitutions) in [("pre", script.pres), ("post", script.posts)] {
            for sub in substitutions where sub.source == word || sub.replacement.contains(word) {
                result.append("\(label) \(sub.line): \(sub.source) -> \(sub.replacement.joined(separator: " "))")
            }
        }
        for group in script.groups where group.members.contains(word) { result.append("group \(group.name) line \(group.line)") }
        for keyword in script.keywords {
            for entry in ruleEntries(keyword) where script.rules[entry.id].pattern.contains(word) {
                result.append("pattern \(keyword.word) \(entry.label) \(entry.number)")
            }
        }
        if script.stop.contains(word) { result.append("stop word") }
        if script.quit.contains(word) { result.append("quit word") }
        return result.isEmpty ? ["not found"] : result
    }

    func notes() {
        let session = state.session
        let unrecognized = session.unrecognized.isEmpty ? "none" : session.unrecognized.map(String.init).joined(separator: " ")
        transcript.append("NOTES \(session.name)")
        transcript += [sourceLine(session.turns, counts: session.counts), "topics: \(rankedCounts(session.topics))", "words: \(rankedCounts(session.words))", "memory: stored=\(session.stored) recalled=\(session.recalled) pending=\(state.memory.texts.count)", "unrecognized: \(unrecognized)"].map { "  \($0)" }
        totalTurns += session.turns
        for source in sources { totalSources[source]! += session.counts[source]! }
    }

    func run(_ lines: [String]) {
        var sessions = 0
        for line in lines {
            if line.hasPrefix("SESSION ") {
                let name = String(line.dropFirst(8))
                sessions += 1
                if sessions > 1 {
                    transcript.append("")
                    if !script.persist.contains("cycles") { resetCycles() }
                    if !script.persist.contains("memory") { state.memory.clear("\(name) 0") }
                }
                state.session = Session(name: name)
                transcript.append(line)
                let texts = script.texts["INITIAL"]!
                transcript += elizaLines(texts[(sessions - 1) % texts.count])
            } else if line.hasPrefix(":") {
                transcript.append(line)
                transcript += command(line).map { "  \($0)" }
            } else {
                transcript.append("YOU: \(line)")
                if isQuit(line) {
                    let texts = script.texts["FINAL"]!
                    transcript += elizaLines(texts[(sessions - 1) % texts.count])
                    notes()
                } else { respond(line) }
            }
        }
        transcript.append("")
        transcript.append("SUMMARY sessions=\(sessions) \(sourceLine(totalTurns, counts: totalSources))")
    }

    func keywordStats() -> [String] {
        let indices = script.keywords.indices.sorted {
            state.keywordUses[$0] == state.keywordUses[$1] ? script.keywords[$0].word < script.keywords[$1].word : state.keywordUses[$0] > state.keywordUses[$1]
        }
        return ["keyword,rank,uses,replies,decomposition_hits"] + indices.map { index in
            let keyword = script.keywords[index]
            let hits = keyword.decomps.map { String(state.hits[$0]) }.joined(separator: "/")
            return "\(keyword.word),\(keyword.rank),\(state.keywordUses[index]),\(state.keywordReplies[index]),\(hits.isEmpty ? "-" : hits)"
        }
    }
}

func writeLines(_ name: String, _ lines: [String]) throws {
    let text = lines.isEmpty ? "" : lines.joined(separator: "\n") + "\n"
    try text.write(toFile: "output/\(name)", atomically: true, encoding: .utf8)
}

func runEliza() throws {
    let script = try loadScript("input/script.txt")
    try FileManager.default.createDirectory(atPath: "output", withIntermediateDirectories: true)
    try writeLines("lint.txt", lintLines(lint(script)))
    let bot = Chatbot(script: script)
    bot.run(try readLines("input/dialogue.txt"))
    try writeLines("transcript.txt", bot.transcript)
    try writeLines("keyword_stats.csv", bot.keywordStats())
    try writeLines("memory_log.txt", bot.state.memory.log)
}

try runEliza()

func isWildcard(_ element: String) -> Bool {
    element == "*" || element == "#" || element.hasPrefix("@")
}

func matchPattern(_ pattern: [String], words: [String], groups: [String: Set<String>]) -> [[String]]? {
    var ends: [Int] = []
    func search(_ position: Int, _ start: Int) -> Bool {
        if position == pattern.count { return start == words.count }
        let element = pattern[position]
        let candidates: ClosedRange<Int>
        if element == "*" { candidates = start...words.count }
        else if start < words.count && (element == "#" || (element.hasPrefix("@") ? groups[String(element.dropFirst()), default: []].contains(words[start]) : element == words[start])) { candidates = (start + 1)...(start + 1) }
        else { return false }
        for end in candidates {
            ends.append(end)
            if search(position + 1, end) { return true }
            ends.removeLast()
        }
        return false
    }
    guard search(0, 0) else { return nil }
    var start = 0
    var bindings: [[String]] = []
    for index in pattern.indices {
        if isWildcard(pattern[index]) { bindings.append(Array(words[start..<ends[index]])) }
        start = ends[index]
    }
    return bindings
}

func patternCovers(_ earlier: [String], later: [String], groups: [String: Set<String>]) -> Bool {
    func elementCovers(_ element: String, _ other: String) -> Bool {
        if element == "#" { return other != "*" }
        if element.hasPrefix("@") {
            let members = groups[String(element.dropFirst())]!
            return other.hasPrefix("@") ? groups[String(other.dropFirst())]!.isSubset(of: members) : members.contains(other)
        }
        return element == other
    }
    func search(_ position: Int, _ start: Int) -> Bool {
        if position == earlier.count { return start == later.count }
        if earlier[position] == "*" { return (start...later.count).contains { search(position + 1, $0) } }
        return start < later.count && elementCovers(earlier[position], later[start]) && search(position + 1, start + 1)
    }
    return search(0, 0)
}

struct MemoryQueue {
    let capacity: Int
    var texts: [String] = []
    var log: [String] = []

    mutating func store(_ prefix: String, keyword: String, text: String) -> Bool {
        if texts.contains(text) { log.append("\(prefix) SKIP \(keyword) \(text)"); return false }
        if texts.count == capacity { log.append("\(prefix) DROP \(texts.removeFirst())") }
        texts.append(text)
        log.append("\(prefix) STORE \(keyword) \(text)")
        return true
    }

    mutating func recall(_ prefix: String) -> String {
        let text = texts.removeFirst()
        log.append("\(prefix) RECALL \(text)")
        return text
    }

    mutating func clear(_ prefix: String) {
        if !texts.isEmpty { log.append("\(prefix) CLEAR \(texts.count)"); texts = [] }
    }
}

func reflect(_ words: [String], post: [String: [String]]) -> [String] {
    words.flatMap { post[$0] ?? [$0] }
}

func binding(_ bindings: [[String]], number: Int) -> [String] {
    number >= 1 && number <= bindings.count ? bindings[number - 1] : []
}

func buildReply(_ template: String, bindings: [[String]], post: [String: [String]]) -> String {
    let bytes = Array(template.utf8)
    var text = ""
    var index = 0
    while index < bytes.count {
        if index + 3 <= bytes.count && bytes[index] == 40 && (48...57).contains(bytes[index + 1]) && bytes[index + 2] == 41 {
            text += reflect(binding(bindings, number: Int(bytes[index + 1] - 48)), post: post).joined(separator: " ")
            index += 3
        } else { text += String(UnicodeScalar(bytes[index])); index += 1 }
    }
    let reply = text.split(separator: " ").joined(separator: " ")
    guard let first = reply.utf8.first, (97...122).contains(first) else { return reply }
    return String(UnicodeScalar(first - 32)) + reply.dropFirst()
}

func restatedWords(_ arguments: [String], bindings: [[String]]) -> [String] {
    arguments.flatMap { isReference($0) ? binding(bindings, number: Int(Array($0.utf8)[1] - 48)) : [$0] }
}

func elizaLines(_ text: String) -> [String] {
    let words = text.split(separator: " ").map(String.init)
    var lines = ["ELIZA: \(words[0])"]
    for word in words.dropFirst() {
        if lines[lines.count - 1].count + 1 + word.count <= 72 { lines[lines.count - 1] += " \(word)" }
        else { lines.append("       \(word)") }
    }
    return lines
}

import Foundation

struct Diagnostic { let line: Int; let code: String; let message: String }
struct Substitution { let source: String; let replacement: [String]; let line: Int }
struct SynonymGroup { let name: String; let members: Set<String>; let line: Int }
struct Item { let kind: String; let text: String; let arguments: [String]; let line: Int }
struct Rule { let kind: String; let pattern: [String]; let line: Int; var items: [Int] = [] }
struct Keyword { let word: String; let rank: Int; let line: Int; var memories: [Int] = []; var decomps: [Int] = [] }

let textDirectives: Set<String> = ["INITIAL", "FINAL", "DEFAULT", "QUESTION", "REPEAT"]
let globalDirectives = textDirectives.union(["QUIT", "STOP", "MEMSIZE", "PERSIST", "PRE", "POST", "SYNON"])
let ruleDirectives: Set<String> = ["DECOMP", "MEMORY"]
let itemDirectives: Set<String> = ["REASM", "GOTO", "NEWKEY", "RESTATE"]

final class Script {
    let lines: [String]
    var texts = Dictionary(uniqueKeysWithValues: textDirectives.map { ($0, [String]()) })
    var quit: Set<String> = []
    var stop: Set<String> = []
    var capacity = 3
    var persist: Set<String> = []
    var pres: [Substitution] = []
    var posts: [Substitution] = []
    var pre: [String: [String]] = [:]
    var post: [String: [String]] = [:]
    var groups: [SynonymGroup] = []
    var groupWords: [String: Set<String>] = [:]
    var keywords: [Keyword] = []
    var keywordMap: [String: Int] = [:]
    var rules: [Rule] = []
    var items: [Item] = []
    var diagnostics: [Diagnostic] = []
    init(lines: [String]) { self.lines = lines }
}

func isWord(_ text: String) -> Bool {
    let bytes = Array(text.utf8)
    return !bytes.isEmpty && bytes.first != 39 && bytes.last != 39 && bytes.allSatisfy {
        (97...122).contains($0) || (48...57).contains($0) || $0 == 39
    }
}

func isNumber(_ text: String) -> Bool {
    (1...2).contains(text.utf8.count) && text.utf8.allSatisfy { (48...57).contains($0) }
}

func isReference(_ text: String) -> Bool {
    let bytes = Array(text.utf8)
    return bytes.count == 3 && bytes[0] == 40 && (48...57).contains(bytes[1]) && bytes[2] == 41
}

func isElement(_ text: String) -> Bool {
    text == "*" || text == "#" || (text.hasPrefix("@") ? isWord(String(text.dropFirst())) : isWord(text))
}

func wellFormed(_ name: String, _ args: [String]) -> Bool {
    if textDirectives.contains(name) || name == "REASM" { return !args.isEmpty }
    switch name {
    case "QUIT", "STOP": return !args.isEmpty && args.allSatisfy(isWord)
    case "MEMSIZE": return args.count == 1 && isNumber(args[0]) && (1...20).contains(Int(args[0])!)
    case "PERSIST": return args.count == 1 && ["cycles", "memory"].contains(args[0])
    case "PRE", "SYNON": return args.count >= 2 && args.allSatisfy(isWord)
    case "POST": return args.count >= 2 && isWord(args[0])
    case "KEY": return args.count == 2 && isWord(args[0]) && isNumber(args[1])
    case "DECOMP", "MEMORY": return !args.isEmpty && args.allSatisfy(isElement)
    case "GOTO": return args.count == 1 && isWord(args[0])
    case "NEWKEY": return args.isEmpty
    case "RESTATE": return args.count >= 2 && isWord(args[0]) && args.dropFirst().allSatisfy { isWord($0) || isReference($0) }
    default: return false
    }
}

func readLines(_ path: String) throws -> [String] {
    let text = try String(contentsOfFile: path, encoding: .utf8)
    return Array(text.components(separatedBy: "\n").dropLast())
}

func loadScript(_ path: String) throws -> Script {
    let script = Script(lines: try readLines(path))
    var keyword: Int?
    var rule: Int?
    var ignoring = false
    var definitions: [String: Int] = [:]
    for (offset, line) in script.lines.enumerated() {
        if line.isEmpty || line.hasPrefix("#") { continue }
        let number = offset + 1
        let words = line.components(separatedBy: " ")
        let name = words[0]
        let args = Array(words.dropFirst())
        let text = line.firstIndex(of: " ").map { String(line[line.index(after: $0)...]) } ?? ""
        if globalDirectives.contains(name) || name == "KEY" {
            keyword = nil; rule = nil; ignoring = false
        } else if ruleDirectives.contains(name) || itemDirectives.contains(name) {
            if ignoring { continue }
            if ruleDirectives.contains(name) { rule = nil }
        }
        let identity: String?
        if name == "MEMSIZE" { identity = name }
        else if ["KEY", "SYNON", "PRE", "POST", "PERSIST"].contains(name), let first = args.first { identity = "\(name) \(first)" }
        else { identity = nil }
        let problem: (String, String)?
        if !globalDirectives.contains(name) && name != "KEY" && !ruleDirectives.contains(name) && !itemDirectives.contains(name) {
            problem = ("SYNTAX", "unknown directive \(name)")
        } else if !wellFormed(name, args) { problem = ("SYNTAX", "bad arguments for \(name)") }
        else if ruleDirectives.contains(name) && keyword == nil { problem = ("ORPHAN", "\(name) without KEY") }
        else if name == "REASM" && rule == nil { problem = ("ORPHAN", "REASM without DECOMP or MEMORY") }
        else if ["GOTO", "NEWKEY", "RESTATE"].contains(name) && (rule == nil || script.rules[rule!].kind == "MEMORY") { problem = ("ORPHAN", "\(name) without DECOMP") }
        else if let identity, let first = definitions[identity] { problem = ("DUPLICATE", "\(identity) first defined at line \(first)") }
        else { problem = nil }
        if let problem {
            script.diagnostics.append(Diagnostic(line: number, code: problem.0, message: problem.1))
            if name == "KEY" && problem.0 == "DUPLICATE" { ignoring = true }
            continue
        }
        if let identity { definitions[identity] = number }
        if textDirectives.contains(name) { script.texts[name]!.append(text); continue }
        switch name {
        case "QUIT": script.quit.formUnion(args)
        case "STOP": script.stop.formUnion(args)
        case "MEMSIZE": script.capacity = Int(args[0])!
        case "PERSIST": script.persist.insert(args[0])
        case "PRE", "POST":
            let substitution = Substitution(source: args[0], replacement: Array(args.dropFirst()), line: number)
            if name == "PRE" { script.pres.append(substitution); script.pre[args[0]] = substitution.replacement }
            else { script.posts.append(substitution); script.post[args[0]] = substitution.replacement }
        case "SYNON":
            script.groups.append(SynonymGroup(name: args[0], members: Set(args), line: number))
            script.groupWords[args[0]] = Set(args)
        case "KEY":
            keyword = script.keywords.count
            script.keywordMap[args[0]] = keyword!
            script.keywords.append(Keyword(word: args[0], rank: Int(args[1])!, line: number))
        case "DECOMP", "MEMORY":
            rule = script.rules.count
            script.rules.append(Rule(kind: name, pattern: args, line: number))
            if name == "DECOMP" { script.keywords[keyword!].decomps.append(rule!) }
            else { script.keywords[keyword!].memories.append(rule!) }
        default:
            script.rules[rule!].items.append(script.items.count)
            script.items.append(Item(kind: name, text: text, arguments: args, line: number))
        }
    }
    return script
}
